  "Show the back, answer with the front": { es: "Mostrar el reverso y responder con el anverso", ar: "اعرض الظهر وأجب بالوجه", zh: "显示背面，用正面作答", sw: "Onyesha nyuma, jibu kwa mbele", sv: "Visa baksidan, svara med framsidan" },
