  "Due soonest": { es: "Las más próximas", ar: "الأقرب موعدًا", zh: "最快到期", sw: "Zinazodaiwa karibuni", sv: "Snarast på tur" },
  "Hardest": { es: "Las más difíciles", ar: "الأصعب", zh: "最难", sw: "Ngumu zaidi", sv: "Svårast" },
